// src/components/layout/WifiPanel.jsx
import React, { useState, useEffect } from 'react';
import { scanWifiNetworks, connectToWifi } from '../../services/api';

const WifiPanel = ({ setIsConnected, closePanel }) => {
  const [networks, setNetworks] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [selectedSsid, setSelectedSsid] = useState('');
  const [password, setPassword] = useState('');
  const [status, setStatus] = useState('');

  const handleScan = async () => {
    setLoading(true);
    setError('');
    setNetworks([]);
    setStatus('Scanning for networks...');
    try {
      const scannedNetworks = await scanWifiNetworks();
      setNetworks(scannedNetworks);
      setStatus(scannedNetworks.length > 0 ? 'Select a network to connect.' : 'No networks found.');
    } catch (err) {
      const errorMessage = err.response?.data?.error || err.message || 'Failed to scan for networks.';
      setError(errorMessage);
      setStatus('');
    } finally {
      setLoading(false);
    }
  };

  // Perform an initial scan on component mount
  useEffect(() => {
    handleScan();
  }, []);

  const handleConnect = async (e, ssid, networkPassword = '') => {
    if (e) e.preventDefault();
    const targetSsid = ssid || selectedSsid;
    if (!targetSsid) return;

    setLoading(true);
    setError('');
    setStatus(`Connecting to ${targetSsid}...`);
    setIsConnected(false);

    try {
      const finalPassword = password || networkPassword;
      const response = await connectToWifi(targetSsid, finalPassword);
      setStatus(response.message || `Successfully connected to ${targetSsid}.`);
      if (response.espSyncError) {
        setError(`ESP Sync failed: ${response.espSyncError}`);
      }
      setIsConnected(true);
      setSelectedSsid(''); // Reset form
      setPassword('');
      setTimeout(closePanel, 2000); // Close panel after successful connection
    } catch (err) {
      const errorMessage = err.response?.data?.error || err.message || 'Failed to connect.';
      setError(errorMessage);
      setStatus('');
      setIsConnected(false);
    } finally {
      setLoading(false);
    }
  };
  
  const requiresPassword = (network) => {
    return network.security && network.security !== 'none';
  };

  return (
    <div className="absolute top-14 right-0 w-80 bg-surface border border-border-color rounded-lg shadow-2xl p-4 z-50 text-on-surface">
      <h3 className="font-bold text-lg mb-2">Wi-Fi Connection</h3>
      
      <button
        onClick={handleScan}
        disabled={loading}
        className="w-full bg-primary text-white font-semibold py-2 px-4 rounded-md hover:bg-purple-700 transition duration-200 disabled:bg-gray-500 disabled:cursor-wait"
      >
        {loading ? 'Scanning...' : 'Re-scan Networks'}
      </button>

      {error && <p className="text-red-400 text-sm mt-3 text-center">{error}</p>}
      {status && !error && <p className="text-on-surface-secondary text-sm mt-3 text-center">{status}</p>}

      {selectedSsid && (
        <form onSubmit={handleConnect} className="mt-4">
          <p className="text-center font-semibold mb-2">Connect to <span className="text-primary">{selectedSsid}</span></p>
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="Password"
            className="w-full bg-background border border-border-color rounded-md px-3 py-2 text-on-background focus:outline-none focus:ring-2 focus:ring-primary"
            autoFocus
          />
          <div className="flex items-center gap-2 mt-2">
            <button
              type="button"
              onClick={() => setSelectedSsid('')}
              className="w-full bg-border-color hover:bg-gray-600 text-on-surface font-semibold py-2 px-4 rounded-md transition"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={loading}
              className="w-full bg-primary text-white font-semibold py-2 px-4 rounded-md hover:bg-purple-700 transition disabled:bg-gray-500"
            >
              {loading ? 'Connecting...' : 'Connect'}
            </button>
          </div>
        </form>
      )}

      {!selectedSsid && networks.length > 0 && (
        <div className="mt-4 max-h-60 overflow-y-auto space-y-1 pr-1">
          {networks.map((net, index) => (
            <div
              key={index}
              onClick={() => {
                if (loading) return;
                if (!requiresPassword(net)) {
                  handleConnect(null, net.ssid, '');
                } else {
                  setSelectedSsid(net.ssid);
                }
              }}
              className="flex items-center justify-between p-2 rounded-md hover:bg-background cursor-pointer"
            >
              <span className="font-medium text-sm">{net.ssid}</span>
              <div className="flex items-center">
                <span className="text-xs mr-2 text-on-surface-secondary">{net.signal_level} dBm</span>
                {requiresPassword(net) && (
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-on-surface-secondary" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M10 2a3 3 0 00-3 3v2H6a2 2 0 00-2 2v8a2 2 0 002 2h8a2 2 0 002-2v-8a2 2 0 00-2-2h-1V5a3 3 0 00-3-3zm-1 3a1 1 0 112 0v2H9V5z" clipRule="evenodd" />
                  </svg>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default WifiPanel;
